import { z } from 'zod';
import {
  CARD_TYPES,
  CardContentSchema,
  clozeAnswer,
  normalizeAnswer,
  type CardContent,
} from './content';
import { SlugSchema } from './schemas';

// The catalog deck file, `ace-deck@2` (BUILD_BRIEF_M6_M8 §7.2, amended 2026-10-11), and
// the publishing warnings (§7.4). Files are often generated by ChatGPT, so validation is
// strict (unknown fields are errors, which catches typos) and every error names the card
// key, the field and the problem. Pure: the CLI and the server both use it.

export const DECK_FILE_FORMAT = 'ace-deck@2';
export const YEARS = ['FE', 'SE', 'TE', 'BE'] as const;
const KEY_PATTERN = /^u\d{1,2}-\d{3}$/;

const text = (max: number) =>
  z
    .string()
    .trim()
    .min(1, 'must not be blank')
    .max(max, `must be at most ${String(max)} characters`);

const YEAR_ONLY = 'must be the syllabus year only, exactly 4 digits, e.g. "2024"';

/** YYYY-MM-DD and a real calendar date. */
const IsoDate = z.custom<string>(
  (v) => {
    if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
    const t = Date.parse(`${v}T00:00:00Z`);
    return !Number.isNaN(t) && new Date(t).toISOString().slice(0, 10) === v;
  },
  { message: 'must be a date written as YYYY-MM-DD' },
);

const CatalogSchema = z
  .strictObject({
    university: text(100),
    pattern: z.custom<string>((v) => typeof v === 'string' && /^\d{4}$/.test(v), {
      message: YEAR_ONLY,
    }),
    year: z.enum(YEARS),
    semester: z.int().min(1).max(8),
    branches: z.array(text(30)).min(1, 'list at least one branch'),
    subject: text(200),
    subjectCodes: z.record(z.string(), text(50).nullable()),
    units: z
      .array(z.strictObject({ number: z.int().min(1).max(99), title: text(200) }))
      .min(1, 'list at least one unit'),
  })
  .superRefine((c, ctx) => {
    const seen = new Set<string>();
    for (const b of c.branches) {
      if (seen.has(b)) {
        ctx.addIssue({ code: 'custom', path: ['branches'], message: `duplicate branch "${b}"` });
      }
      seen.add(b);
    }
    for (const b of c.branches) {
      if (!(b in c.subjectCodes)) {
        ctx.addIssue({
          code: 'custom',
          path: ['subjectCodes'],
          message: `missing branch "${b}" (give its code, or null)`,
        });
      }
    }
    for (const key of Object.keys(c.subjectCodes)) {
      if (!c.branches.includes(key)) {
        ctx.addIssue({
          code: 'custom',
          path: ['subjectCodes'],
          message: `not a branch: "${key}" (keys must match catalog.branches)`,
        });
      }
    }
    const numbers = new Set<number>();
    for (const u of c.units) {
      if (numbers.has(u.number)) {
        ctx.addIssue({
          code: 'custom',
          path: ['units'],
          message: `duplicate unit number ${String(u.number)}`,
        });
      }
      numbers.add(u.number);
    }
  });

const FileSchema = z.strictObject({
  format: z.literal(DECK_FILE_FORMAT, { error: `must be "${DECK_FILE_FORMAT}"` }),
  slug: SlugSchema,
  version: z.int().min(1),
  title: text(200),
  description: text(2000),
  catalog: CatalogSchema,
  /** Paise; 0 = free (M8: more than 0 = paid). */
  price: z.int().min(0),
  author: text(200),
  reviewedBy: text(200).nullable().default(null),
  lastVerifiedAt: IsoDate,
  cards: z.array(z.unknown()).min(1, 'a deck needs at least one card'),
});

export type DeckCatalogInfo = z.infer<typeof CatalogSchema>;
export type DeckFileCard = { key: string; unit: number } & CardContent;
export type DeckFile = Omit<z.infer<typeof FileSchema>, 'cards'> & { cards: DeckFileCard[] };

export type DeckFileResult = { ok: true; deck: DeckFile } | { ok: false; errors: string[] };

/** Optional content fields a file may leave out. */
const DEFAULTS: Record<CardContent['type'], Record<string, unknown>> = {
  basic: {},
  mcq: { explanation: null },
  cloze: { accepted: [], hint: null, extra: null },
  short: { explanation: null },
  long: { marks: null, modelAnswer: null },
};

const pathOf = (path: readonly PropertyKey[]) => path.map(String).join('.');

function describe(issue: z.core.$ZodIssue): string {
  return issue.message;
}

/** A card's M6 content (the file's card without `key` and `unit`). */
export function cardContentOf(card: DeckFileCard): CardContent {
  const { key: _key, unit: _unit, ...content } = card;
  return content;
}

/** Validates a parsed JSON value as an `ace-deck@2` file. */
export function validateDeckFile(input: unknown): DeckFileResult {
  const errors: string[] = [];
  const top = FileSchema.safeParse(input);
  if (!top.success) {
    for (const issue of top.error.issues) {
      if (issue.path[0] === 'cards' && issue.path.length > 1) continue; // reported below
      errors.push(`${pathOf(issue.path) || 'file'}: ${describe(issue)}`);
    }
  }
  const rawCards =
    typeof input === 'object' &&
    input !== null &&
    Array.isArray((input as { cards?: unknown }).cards)
      ? (input as { cards: unknown[] }).cards
      : [];
  const unitNumbers = new Set(top.success ? top.data.catalog.units.map((u) => u.number) : []);
  const keyIndex = new Map<string, number>();
  const cards: DeckFileCard[] = [];

  rawCards.forEach((raw, i) => {
    const where = `cards[${String(i)}]`;
    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
      errors.push(`${where}: must be an object`);
      return;
    }
    const { key, unit, ...rest } = raw as Record<string, unknown>;
    const label = typeof key === 'string' && KEY_PATTERN.test(key) ? key : where;
    const cardErrors: string[] = [];
    const fail = (field: string, message: string) => {
      cardErrors.push(`${label} · ${field}: ${message}`);
    };

    if (typeof key !== 'string' || !KEY_PATTERN.test(key)) {
      fail('key', `must look like "u1-001" (u<unit>-<3 digits>), got ${JSON.stringify(key)}`);
    } else {
      const first = keyIndex.get(key);
      if (first !== undefined) fail('key', `duplicate key (also used by cards[${String(first)}])`);
      else keyIndex.set(key, i);
    }
    if (typeof unit !== 'number' || !Number.isInteger(unit)) {
      fail('unit', 'must be a whole number');
    } else if (top.success && !unitNumbers.has(unit)) {
      fail('unit', `unit ${String(unit)} is not in catalog.units`);
    }
    const type = rest.type;
    if (typeof type !== 'string' || !(CARD_TYPES as readonly string[]).includes(type)) {
      fail('type', `must be one of ${CARD_TYPES.join(', ')}, got ${JSON.stringify(type)}`);
    } else {
      const withDefaults = { ...DEFAULTS[type as CardContent['type']], ...rest };
      const content = CardContentSchema.safeParse(withDefaults);
      if (!content.success) {
        for (const issue of content.error.issues)
          fail(pathOf(issue.path) || 'card', describe(issue));
      } else if (cardErrors.length === 0) {
        cards.push({ key: key as string, unit: unit as number, ...content.data });
      }
    }
    errors.push(...cardErrors);
  });

  if (errors.length > 0 || !top.success) return { ok: false, errors };
  return { ok: true, deck: { ...top.data, cards } };
}

// ---------------------------------------------------------------- warnings (§7.4)

export interface DeckWarning {
  code:
    | 'duplicate_question'
    | 'correct_option_longest'
    | 'few_key_points'
    | 'unit_without_long'
    | 'marks_in_question'
    | 'meta_key_point'
    | 'basic_cloze_same_term';
  message: string;
  /** The cards concerned, in file order. */
  keys: string[];
}

/** More than this share of MCQs having the longest option correct is a pattern. */
export const LONGEST_CORRECT_LIMIT = 0.4;
const MARKS_NOTE = /[[(]\s*\d+\s*marks?\s*[\])]/i;
const META_KEY_POINT = /^(gives|uses|notes|mentions|explains that)\b/i;

function questionText(c: CardContent): string {
  switch (c.type) {
    case 'basic':
      return c.front;
    case 'cloze':
      return c.text;
    default:
      return c.question;
  }
}

/** Warnings don't block publishing; they point at likely mistakes (§7.4). */
export function deckWarnings(deck: DeckFile): DeckWarning[] {
  const warnings: DeckWarning[] = [];

  const byQuestion = new Map<string, string[]>();
  for (const card of deck.cards) {
    const q = normalizeAnswer(questionText(card));
    byQuestion.set(q, [...(byQuestion.get(q) ?? []), card.key]);
  }
  for (const keys of byQuestion.values()) {
    if (keys.length > 1) {
      warnings.push({
        code: 'duplicate_question',
        message: `Same question in ${keys.join(', ')}`,
        keys,
      });
    }
  }

  const mcqs = deck.cards.filter((c) => c.type === 'mcq');
  const longestCorrect = mcqs.filter((c) => {
    const len = (id: string) => c.options.find((o) => o.id === id)?.text.trim().length ?? 0;
    const correct = len(c.correct);
    return c.options.every((o) => o.id === c.correct || o.text.trim().length < correct);
  });
  if (mcqs.length > 0 && longestCorrect.length / mcqs.length > LONGEST_CORRECT_LIMIT) {
    const pct = Math.round((longestCorrect.length / mcqs.length) * 100);
    warnings.push({
      code: 'correct_option_longest',
      message: `The correct option is the longest in ${String(longestCorrect.length)} of ${String(mcqs.length)} MCQs (${String(pct)}%); students can guess by length`,
      keys: longestCorrect.map((c) => c.key),
    });
  }

  for (const card of deck.cards) {
    if (card.type !== 'long') continue;
    if (card.keyPoints.length < 3) {
      warnings.push({
        code: 'few_key_points',
        message: `${card.key}: only ${String(card.keyPoints.length)} key points (aim for at least 3)`,
        keys: [card.key],
      });
    }
    if (MARKS_NOTE.test(card.question)) {
      warnings.push({
        code: 'marks_in_question',
        message: `${card.key}: the question mentions marks; put them in "marks" instead`,
        keys: [card.key],
      });
    }
    const meta = card.keyPoints.filter((p) => META_KEY_POINT.test(p.trim()));
    if (meta.length > 0) {
      warnings.push({
        code: 'meta_key_point',
        message: `${card.key}: key point "${meta[0] ?? ''}" describes the answer instead of stating the point`,
        keys: [card.key],
      });
    }
  }

  for (const unit of deck.catalog.units) {
    if (!deck.cards.some((c) => c.unit === unit.number && c.type === 'long')) {
      warnings.push({
        code: 'unit_without_long',
        message: `Unit ${String(unit.number)} (${unit.title}) has no long-answer cards`,
        keys: [],
      });
    }
  }

  const clozes = deck.cards.filter((c) => c.type === 'cloze');
  for (const basic of deck.cards) {
    if (basic.type !== 'basic') continue;
    const back = normalizeAnswer(basic.back);
    for (const cloze of clozes) {
      const answers = [clozeAnswer(cloze), ...cloze.accepted].map(normalizeAnswer);
      if (answers.includes(back)) {
        warnings.push({
          code: 'basic_cloze_same_term',
          message: `${basic.key} (basic) and ${cloze.key} (cloze) test the same term`,
          keys: [basic.key, cloze.key],
        });
      }
    }
  }

  return warnings;
}
